module protest_optimization (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire signed [7:0] x_coords [0:7],\n    input wire signed [7:0] y_coords [0:7],\n    input wire [3:0] n,\n    input wire [7:0] d,\n    output reg [15:0] result,\n    output reg done,\n    output reg impossible\n);\n\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] COMPUTE_BOUNDS = 4'd1;\n    localparam [3:0] SEARCH_X = 4'd2;\n    localparam [3:0] SEARCH_Y = 4'd3;\n    localparam [3:0] CHECK_FEASIBLE = 4'd4;\n    localparam [3:0] COMPUTE_DISTANCE = 4'd5;\n    localparam [3:0] UPDATE_MIN = 4'd6;\n    localparam [3:0] DONE_STATE = 4'd7;\n    \n    reg [3:0] state;\n    reg signed [7:0] min_x, max_x;\n    reg signed [7:0] min_y, max_y;\n    reg [3:0] citizen_idx;\n    reg signed [7:0] search_x, search_y;\n    reg [7:0] x_offset, y_offset;\n    reg [15:0] total_distance;\n    reg [15:0] best_distance;\n    reg feasibility_flag;\n    reg [3:0] check_idx;\n    reg [7:0] cycle_counter;\n    localparam [7:0] MAX_CYCLES = 8'd200;\n\n    // Dependency: Number of walls to climb for single citizen\n    function automatic [7:0] calc_offset;\n        input signed [7:0] a;\n        input signed [7:0] b;\n        reg [7:0] temp_diff;\n        begin\n            if (a > b) temp_diff = a - b;\n            else temp_diff = b - a;\n            calc_offset = temp_diff;\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            impossible <= 1'b0;\n            min_x <= 8'sd0;\n            max_x <= 8'sd0;\n            min_y <= 8'sd0;\n            max_y <= 8'sd0;\n            citizen_idx <= 4'd0;\n            search_x <= 8'sd0;\n            search_y <= 8'sd0;\n            total_distance <= 16'd0;\n            best_distance <= 16'hFFFF;\n            feasibility_flag <= 1'b0;\n            check_idx <= 4'd0;\n            result <= 16'd0;\n            cycle_counter <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    impossible <= 1'b0;\n                    cycle_counter <= 8'd0;\n                    if (start) begin\n                        citizen_idx <= 4'd0;\n                        state <= COMPUTE_BOUNDS;\n                    end\n                end\n                \n                COMPUTE_BOUNDS: begin\n                    if (citizen_idx < n) begin\n                        if (citizen_idx == 0) begin\n                            min_x <= x_coords[0];\n                            max_x <= x_coords[0];\n                            min_y <= y_coords[0];\n                            max_y <= y_coords[0];\n                        end else begin\n                            if (x_coords[citizen_idx] < min_x) min_x <= x_coords[citizen_idx];\n                            if (x_coords[citizen_idx] > max_x) max_x <= x_coords[citizen_idx];\n                            if (y_coords[citizen_idx] < min_y) min_y <= y_coords[citizen_idx];\n                            if (y_coords[citizen_idx] > max_y) max_y <= y_coords[citizen_idx];\n                        end\n                        citizen_idx <= citizen_idx + 1'b1;\n                    end else begin\n                        search_x <= (min_x > d) ? min_x - d : 8'sd0;\n                        search_y <= (min_y > d) ? min_y - d : 8'sd0;\n                        state <= SEARCH_X;\n                    end\n                end\n                \n                SEARCH_X: begin\n                    if (search_x <= (max_x + d)) begin\n                        search_y <= (min_y > d) ? min_y - d : 8'sd0;\n                        state <= SEARCH_Y;\n                    end else begin\n                        impossible <= (best_distance == 16'hFFFF) ? 1'b1 : 1'b0;\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                SEARCH_Y: begin\n                    if (search_y <= (max_y + d)) begin\n                        check_idx <= 4'd0;\n                        feasibility_flag <= 1'b1;\n                        state <= CHECK_FEASIBLE;\n                    end else begin\n                        search_x <= search_x + 1'b1;\n                        state <= SEARCH_X;\n                    end\n                end\n                \n                CHECK_FEASIBLE: begin\n                    if (check_idx < n) begin\n                        x_offset = calc_offset(search_x, x_coords[check_idx]);\n                        y_offset = calc_offset(search_y, y_coords[check_idx]);\n                        if ((x_offset + y_offset) > d) \n                            feasibility_flag <= 1'b0;\n                        check_idx <= check_idx + 1'b1;\n                    end else begin\n                        if (feasibility_flag) begin\n                            check_idx <= 4'd0;\n                            total_distance <= 16'd0;\n                            state <= COMPUTE_DISTANCE;\n                        end else begin\n                            search_y <= search_y + 1'b1;\n                            state <= SEARCH_Y;\n                        end\n                    end\n                end\n                \n                COMPUTE_DISTANCE: begin\n                    if (check_idx < n) begin\n                        x_offset = calc_offset(search_x, x_coords[check_idx]);\n                        y_offset = calc_offset(search_y, y_coords[check_idx]);\n                        total_distance <= total_distance + x_offset + y_offset;\n                        check_idx <= check_idx + 1'b1;\n                        cycle_counter <= cycle_counter + 1'b1;\n                        if (cycle_counter >= MAX_CYCLES) begin\n                            state <= DONE_STATE;\n                        end\n                    end else begin\n                        if (total_distance < best_distance) \n                            best_distance <= total_distance;\n                        search_y <= search_y + 1'b1;\n                        state <= SEARCH_Y;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    result <= (impossible) ? 16'd0 : best_distance;\n                    if (cycle_counter >= MAX_CYCLES) begin\n                        impossible <= 1'b1;\n                    end\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule